package completion

// ZshScript returns the zsh completion script for gandalf.
// It completes only subcommands (check, completion, mellon, friend, help, version)
// as requested, without flag completion.
func ZshScript() string {
	return `#compdef gandalf
# zsh completion for gandalf - generated by 'gandalf completion zsh'
# To enable:
#   mkdir -p ~/.zsh/completions
#   gandalf completion zsh > ~/.zsh/completions/_gandalf
#   Add to ~/.zshrc: fpath=(~/.zsh/completions $fpath); autoload -Uz compinit && compinit
#   Restart shell or run: compinit

_gandalf() {
  local -a completions
  local -a commands
  commands=(
    'check:Evaluate password strength with Middle-earth lore'
    'completion:Generate shell completion script'
    'mellon:Reveal the Doors of Durin'
    'friend:Reveal the Doors of Durin (translation)'
    'help:Show help'
    'version:Show version'
  )

  _arguments -C \
    "1: :->cmds" \
    "*::arg:->args"

  case $state in
    cmds)
      _describe 'gandalf commands' commands
      ;;
    args)
      case $words[1] in
        completion)
          local -a shells
          shells=(
            'zsh:Zsh completion'
          )
          _describe 'shell' shells
          ;;
      esac
      ;;
  esac
}

(( $+functions[compdef] )) && compdef _gandalf gandalf
`
}

// SupportedShells lists shells with completion support.
var SupportedShells = []string{"zsh"}

// IsSupported reports whether shell is supported.
func IsSupported(shell string) bool {
	for _, s := range SupportedShells {
		if s == shell {
			return true
		}
	}
	return false
}
